-- CUBE seed: internal hypotheses only. This does not create live offers or demand.
begin;
alter table public.marketplace_cube_hypotheses add column if not exists price_hypothesis text;
on conflict (id) do update set
 buyer_segment=excluded.buyer_segment,
 problem_statement=excluded.problem_statement,
 offer_hypothesis=excluded.offer_hypothesis,
 candidate_silo=excluded.candidate_silo,
 priority=excluded.priority,
 fulfillment_contract=excluded.fulfillment_contract,
 evidence_required=excluded.evidence_required,
 price_hypothesis=excluded.price_hypothesis,
 updated_at=now()
where public.marketplace_cube_hypotheses.state='HYPOTHESIS_UNVALIDATED';
update public.marketplace_cube_hypotheses h set price_hypothesis = h.evidence_required->>'price_hypothesis_nzd'
where h.id like 'H%' and h.price_hypothesis is null and h.evidence_required ? 'price_hypothesis_nzd';
commit;
